% diseno_mandriles.m - AOS Mandriles V2 unloading secuencial para GNU Octave.
script_dir=fileparts(mfilename('fullpath'));AOS_root=fileparts(fileparts(fileparts(script_dir)));addpath(fullfile(AOS_root,'src'),'-begin');iniciar_aos;cd(AOS_root);
global CONFIG_ACTIVA AOSDAT_ACTIVO;if isstruct(CONFIG_ACTIVA)&&~isempty(fieldnames(CONFIG_ACTIVA)),param=aos_normalizar_config(CONFIG_ACTIVA,'GL');origen=AOSDAT_ACTIVO;else,param=aos_config_base();origen='CONFIGURACION_BASE';endif
param=mandriles_defaults(param);if ~isfield(param,'D_packer')||isempty(param.D_packer),param.D_packer=param.D_iny;endif
fprintf('\n--- DISENO DE MANDRILES V2 AUTOMATICO ---\n');fprintf('Origen                    : %s\n',origen);fprintf('P iny superficie          : %.1f bar\n',param.P_iny_sup/1e5);fprintf('Profundidad objetivo      : %.1f m MD\n',param.D_packer);fprintf('Qiny configurado          : %.0f Sm3/d\n',param.Q_iny*86400);
r=aos_preguntar_sn('Desea modificar parametros de diseno? (s/n) [n]: ',false);if r,x=input(sprintf('  P iny superficie (bar) [%.1f]: ',param.P_iny_sup/1e5));if ~isempty(x),param.P_iny_sup=x*1e5;endif;x=input(sprintf('  Profundidad limite MD (m) [%.1f]: ',param.D_packer));if ~isempty(x),param.D_packer=x;endif;x=input(sprintf('  Qiny objetivo (Sm3/d) [%.0f]: ',param.Q_iny*86400));if ~isempty(x),param=aos_set_qiny(param,x,'fijo');endif;txt=input('  Maximo de estaciones [AUTOMATICO]: ','s');if isempty(strtrim(txt)),param.mand_N_max=0;else,x=str2double(txt);if isfinite(x),param.mand_N_max=max(1,round(x));endif,endif;x=input(sprintf('  Diferencial apertura (bar) [%.1f]: ',param.mand_dP_apertura_bar));if ~isempty(x),param.mand_dP_apertura_bar=max(x,0);endif;endif
param=aos_sincronizar_config(param,'GL');R=mandriles_diseno_unloading(param);mandriles_imprimir_resultado(R);h_fig=mandriles_plot_v2(R);assignin('base','MANDRILES_V2_RESULTADO',R);fprintf('\nResultado disponible en MANDRILES_V2_RESULTADO.\n');
fprintf('\n--- EXPORTAR REPORTE DE MANDRILES ---\n 1 - Ligero\n 2 - Enriquecido con grafico\n 0 - No exportar\n');op=input('Seleccione una opcion (1/2/0): ');if ~isempty(op)&&op==1,exportar_aosrpt_mandriles(R,false);elseif ~isempty(op)&&op==2,exportar_aosrpt_mandriles(R,true);else,fprintf('No se exporto el reporte.\n');endif
